 'use strict';
-// Implement the public contract in TASK.md.
-module.exports = {};
+
+const DEFAULTS = Object.freeze({
+  port: 3000,
+  host: '127.0.0.1',
+  retries: 2,
+  logLevel: 'info'
+});
+
+const ALLOWED_KEYS = new Set(Object.keys(DEFAULTS));
+const LOG_LEVELS = new Set(['debug', 'info', 'warn', 'error']);
+
+function parseConfig(text) {
+  if (typeof text !== 'string') {
+    throw new Error('Configuration must be a JSON string');
+  }
+
+  let parsed;
+  try {
+    parsed = JSON.parse(text);
+  } catch {
+    throw new Error('Configuration contains invalid JSON');
+  }
+
+  if (parsed === null || Array.isArray(parsed) || typeof parsed !== 'object') {
+    throw new Error('Configuration must be a JSON object');
+  }
+
+  for (const key of Object.keys(parsed)) {
+    if (!ALLOWED_KEYS.has(key)) {
+      throw new Error(`Unknown configuration key: ${key}`);
+    }
+  }
+
+  const result = {
+    port: hasOwn(parsed, 'port') ? parsed.port : DEFAULTS.port,
+    host: hasOwn(parsed, 'host') ? parsed.host : DEFAULTS.host,
+    retries: hasOwn(parsed, 'retries') ? parsed.retries : DEFAULTS.retries,
+    logLevel: hasOwn(parsed, 'logLevel') ? parsed.logLevel : DEFAULTS.logLevel
+  };
+
+  if (!Number.isInteger(result.port) || result.port < 1 || result.port > 65535) {
+    throw new Error('port must be an integer from 1 to 65535');
+  }
+  if (!Number.isInteger(result.retries) || result.retries < 0 || result.retries > 10) {
+    throw new Error('retries must be an integer from 0 to 10');
+  }
+  if (typeof result.host !== 'string' || result.host.length < 1 || result.host.length > 253 || /\s/.test(result.host)) {
+    throw new Error('host must be 1 to 253 characters with no whitespace');
+  }
+  if (typeof result.logLevel !== 'string' || !LOG_LEVELS.has(result.logLevel)) {
+    throw new Error('logLevel must be debug, info, warn, or error');
+  }
+
+  return result;
+}
+
+function hasOwn(object, key) {
+  return Object.prototype.hasOwnProperty.call(object, key);
+}
+
+module.exports = { parseConfig };
